import React from 'react';
import {AbsoluteFill, Easing, interpolate} from 'remotion';
import {useS, en, clamp, DUR, Fondo} from './kit';

const W = 1080;
const H = 1920;

const SALMO = en('Salmo');
const MIEDO = en('miedo');
const PECHO = en('pecho');
const NOCHE = en('noche');
const HABITA = en('habita');
const ABRIGO = en('abrigo');
const ALTISIMO = en('Altísimo');
const SOMBRA = en('sombra');
const ESPERANZA = en('Esperanza');
const CASTILLO = en('castillo');
const DIOS = en('Dios');
const CONFIO = en('confío');
const PLUMAS = en('plumas');
const CUBRIRA = en('cubrirá');
const ALAS = en('alas');
const SEGURO = en('seguro');
const TEMERAS = en('temerás');
const ESPANTO = en('espanto');
const NOCTURNO = en('nocturno');
const SAETA = en('saeta');
const VUELE = en('vuele');
const DIA = en('día');
const SOMBRA2 = en('sombra');
const QUITA = en('quita');
const COBIJA = en('cobija');
const DUERME = en('Duerme');
const PAZ = en('paz');
const VELA = en('vela');
const AMEN = en('Amén');

const mezcla = (a: number[], b: number[], k: number) => `rgb(${a.map((x, i) => Math.round(x + (b[i] - x) * k)).join(',')})`;

const Cielo: React.FC<{k: number}> = ({k}) => {
  const arriba = mezcla([5, 8, 20], [18, 28, 60], k);
  const medio = mezcla([10, 12, 30], [40, 55, 110], k);
  const abajo = mezcla([15, 18, 40], [80, 90, 140], k);
  return <AbsoluteFill style={{background: `linear-gradient(180deg, ${arriba} 0%, ${medio} 55%, ${abajo} 100%)`}} />;
};

const Estrellas: React.FC<{s: number; op: number}> = ({s, op}) => (
  <AbsoluteFill style={{opacity: op}}>
    {Array.from({length: 90}).map((_, i) => {
      const x = (i * 173) % W;
      const y = (i * 281) % 1100;
      const r = 1.2 + (i % 3) * 0.8;
      const brillo = 0.35 + 0.65 * Math.abs(Math.sin(s * 0.6 + i * 1.7));
      return <div key={i} style={{position: 'absolute', left: x, top: y, width: r * 2, height: r * 2, borderRadius: r, background: '#fff8e8', opacity: brillo * op, boxShadow: '0 0 6px #ffe8b0'}} />;
    })}
  </AbsoluteFill>
);

const Luna: React.FC<{s: number; k: number}> = ({s, k}) => {
  const y = interpolate(k, [0, 1], [300, 420], clamp);
  const r = 90 + Math.sin(s * 0.8) * 3;
  const brillo = 0.6 + 0.4 * Math.sin(s * 0.4);
  return (
    <div style={{position: 'absolute', left: W / 2 - r * 2.5, top: y - r * 2.5, width: r * 5, height: r * 5, opacity: k}}>
      <div style={{position: 'absolute', inset: 0, borderRadius: '50%', background: 'radial-gradient(circle, rgba(255,245,210,0.45) 0%, rgba(255,220,160,0.15) 40%, transparent 75%)'}} />
      <div style={{position: 'absolute', left: r * 1.5, top: r * 1.5, width: r * 2, height: r * 2, borderRadius: '50%', background: 'radial-gradient(circle at 35% 35%, #fffef5 0%, #ffe8b0 55%, #e8c870 100%)', boxShadow: `0 0 ${80 * brillo}px ${20 * brillo}px rgba(255,230,160,0.35)`}} />
    </div>
  );
};

const RayosLuna: React.FC<{k: number; s: number}> = ({k, s}) => (
  <AbsoluteFill style={{opacity: k * 0.25, mixBlendMode: 'screen'}}>
    {Array.from({length: 7}).map((_, i) => {
      const ang = -30 + i * 10 + Math.sin(s * 0.2 + i) * 1.5;
      return <div key={i} style={{position: 'absolute', left: W / 2 - 30, top: 420, width: 60, height: 1600, transformOrigin: '50% 0%', transform: `rotate(${ang + 180}deg)`, background: 'linear-gradient(180deg, rgba(255,240,200,0.35), transparent 85%)', filter: 'blur(18px)'}} />;
    })}
  </AbsoluteFill>
);

const NubesBajas: React.FC<{s: number; miedo: number}> = ({s, miedo}) => (
  <AbsoluteFill>
    {Array.from({length: 5}).map((_, i) => {
      const x = -150 + i * 300 + Math.sin(s * 0.15 + i) * 80 * miedo;
      const y = 200 + (i % 2) * 180 + Math.cos(s * 0.1 + i) * 40;
      const esc = 0.8 + miedo * 0.4;
      return (
        <div key={i} style={{position: 'absolute', left: x, top: y, width: 500 * esc, height: 180 * esc, borderRadius: 180, background: `radial-gradient(ellipse at 50% 40%, rgba(30,30,50,${0.6 * miedo}), rgba(15,15,35,${0.3 * miedo}) 70%)`, filter: 'blur(12px)', opacity: miedo}} />
      );
    })}
  </AbsoluteFill>
);

const Pecho: React.FC<{s: number; aprieta: number}> = ({s, aprieta}) => {
  const latido = Math.sin(s * 5.5) * 8 * aprieta;
  const respira = Math.sin(s * 1.2) * 4;
  return (
    <div style={{position: 'absolute', left: W / 2 - 120, top: 900 + respira, transform: `scaleX(${1 - 0.15 * aprieta})`}}>
      <svg width={240} height={200} viewBox="0 0 240 200">
        <path d="M120 40 C 60 40, 20 100, 20 140 Q 20 180, 120 190 Q 220 180, 220 140 C 220 100, 180 40, 120 40" fill="none" stroke="#ff6b6b" strokeWidth={3 + 2 * aprieta} strokeDasharray="8 6" strokeDashoffset={s * 30} opacity={0.6 + 0.4 * aprieta} style={{filter: 'drop-shadow(0 0 8px #ff6b6b)'}} />
        <path d="M120 40 C 60 40, 20 100, 20 140 Q 20 180, 120 190 Q 220 180, 220 140 C 220 100, 180 40, 120 40" fill="rgba(255,107,107,0.1)" opacity={aprieta} />
      </svg>
      <div style={{position: 'absolute', left: 100 + latido, top: 80, width: 40, height: 40, borderRadius: '50%', background: 'radial-gradient(circle, #ff6b6b, #c0392b)', opacity: aprieta}} />
    </div>
  );
};

const Alas: React.FC<{s: number; k: number}> = ({s, k}) => {
  const aleteo = Math.sin(s * 2.5) * 15 * k;
  const apertura = k * 0.85;
  return (
    <div style={{position: 'absolute', left: W / 2, top: 700, transform: 'translateX(-50%)'}}>
      {[-1, 1].map((lado) => (
        <svg key={lado} width={400} height={500} viewBox="0 0 400 500" style={{position: 'absolute', left: lado * 200 * apertura, top: -50, transform: `scaleX(${lado}) rotate(${lado * aleteo}deg)`, transformOrigin: 'right center', opacity: k, filter: 'drop-shadow(0 10px 40px rgba(255,240,210,0.3))'}}>
          <defs>
            <linearGradient id={`ala${lado}`} x1="0" y1="0" x2="1" y2="1">
              <stop offset="0%" stopColor="#fffef8" />
              <stop offset="50%" stopColor="#fff5e0" />
              <stop offset="100%" stopColor="#ffe8c0" />
            </linearGradient>
          </defs>
          <path d="M20 10 Q 100 50, 180 120 Q 280 200, 350 350 Q 300 400, 20 480 Q 50 300, 80 200 Q 100 120, 20 10" fill="url(#ala1)" stroke="rgba(255,230,180,0.6)" strokeWidth={1.5} />
          {[80, 150, 220, 290].map((y, j) => (
            <path key={j} d={`M40 ${y} Q 120 ${y - 30}, 200 ${y} Q 280 ${y - 30}, 360 ${y}`} fill="none" stroke="rgba(255,240,210,0.35)" strokeWidth={1.5} strokeLinecap="round" />
          ))}
        </svg>
      ))}
      <div style={{position: 'absolute', left: -60, top: 200, width: 120, height: 120, borderRadius: '50%', background: 'radial-gradient(circle at 40% 40%, rgba(255,250,230,0.9), rgba(255,220,160,0.3) 60%, transparent)', opacity: k, filter: 'blur(8px)'}} />
    </div>
  );
};

const Plumas: React.FC<{s: number; k: number}> = ({s, k}) => (
  <AbsoluteFill>
    {Array.from({length: 18}).map((_, i) => {
      const t0 = PLUMAS + i * 0.12;
      const aparece = interpolate(s, [t0, t0 + 0.6], [0, 1], clamp) * k;
      const x = 200 + (i * 47) % 680 + Math.sin(s * 0.8 + i) * 40;
      const y = 1100 - aparece * 400 - Math.cos(s * 0.5 + i) * 60;
      const rot = (i % 3 - 1) * 30 + Math.sin(s * 1.2 + i) * 10;
      return (
        <div key={i} style={{position: 'absolute', left: x, top: y, opacity: aparece, transform: `rotate(${rot}deg) scale(${aparece})`, filter: 'drop-shadow(0 4px 12px rgba(255,240,210,0.4))'}}>
          <svg width={50} height={80} viewBox="0 0 50 80">
            <path d="M25 2 Q 45 20, 25 78 Q 5 20, 25 2" fill="#fffef8" stroke="#ffe8c0" strokeWidth={1} />
            <path d="M25 10 Q 35 35, 25 70" fill="none" stroke="rgba(255,230,180,0.5)" strokeWidth={1.5} />
          </svg>
        </div>
      );
    })}
  </AbsoluteFill>
);

const Escudo: React.FC<{s: number; k: number}> = ({s, k}) => {
  const pulso = 1 + 0.05 * Math.sin(s * 3) * k;
  return (
    <div style={{position: 'absolute', left: W / 2 - 150 * pulso, top: 600 - 50 * k, width: 300 * pulso, height: 400 * pulso, opacity: k, transformOrigin: 'center center'}}>
      <svg width={300} height={400} viewBox="0 0 300 400" style={{filter: 'drop-shadow(0 0 60px rgba(255,230,160,0.5))'}}>
        <defs>
          <radialGradient id="escudoGrad" cx="50%" cy="30%" r="70%">
            <stop offset="0%" stopColor="#fffef8" stopOpacity={0.4} />
            <stop offset="50%" stopColor="#ffe8b0" stopOpacity={0.2} />
            <stop offset="100%" stopColor="#ffd080" stopOpacity={0.05} />
          </radialGradient>
        </defs>
        <path d="M150 20 L280 80 Q 280 250, 150 380 Q 20 250, 20 80 Z" fill="url(#escudoGrad)" stroke="#ffe8b0" strokeWidth={2} strokeDasharray="10 8" strokeDashoffset={s * 20} />
        <path d="M150 50 L240 110 Q 240 220, 150 320 Q 60 220, 60 110 Z" fill="none" stroke="rgba(255,235,180,0.5)" strokeWidth={1.5} />
      </svg>
    </div>
  );
};

const Saetas: React.FC<{s: number; k: number}> = ({s, k}) => (
  <AbsoluteFill>
    {Array.from({length: 6}).map((_, i) => {
      const t0 = SAETA + i * 0.15;
      const vuela = interpolate(s, [t0, t0 + 1.2], [0, 1], {...clamp, easing: Easing.in(Easing.quad)}) * k;
      const x = (i % 2 ? -100 : W + 100) + (i % 2 ? 1 : -1) * vuela * (W + 200);
      const y = 300 + (i * 220) % 800;
      const rot = (i % 2 ? -30 : 30) + Math.sin(s * 10 + i) * 5;
      return (
        <div key={i} style={{position: 'absolute', left: x, top: y, transform: `rotate(${rot}deg)`, opacity: k * (1 - vuela * 0.5)}}>
          <svg width={120} height={20} viewBox="0 0 120 20">
            <defs>
              <linearGradient id={`saeta${i}`} x1="0" y1="0" x2="1" y2="0">
                <stop offset="0%" stopColor="#ff6b6b" />
                <stop offset="100%" stopColor="#ffaaaa" />
              </linearGradient>
            </defs>
            <path d="M0 10 L100 10 L120 10 L100 16 L100 4 Z" fill="url(#saeta1)" />
            <path d="M100 10 L90 16 L100 10 L90 4 Z" fill="#ff6b6b" />
          </svg>
        </div>
      );
    })}
  </AbsoluteFill>
);

const SaetasDisueltas: React.FC<{s: number; k: number}> = ({s, k}) => (
  <AbsoluteFill>
    {Array.from({length: 30}).map((_, i) => {
      const t0 = TEMERAS + 0.5 + i * 0.08;
      const aparece = interpolate(s, [t0, t0 + 0.4], [0, 1], clamp) * k;
      const x = W / 2 + Math.cos(i * 2.1) * (80 + s * 120 * k);
      const y = 600 + Math.sin(i * 2.1) * (80 + s * 120 * k);
      const rot = i * 2.1 + s * 3;
      return (
        <div key={i} style={{position: 'absolute', left: x, top: y, transform: `rotate(${rot}deg) scale(${aparece})`, opacity: aparece * (1 - interpolate(s, [t0 + 1, t0 + 2], [0, 1], clamp))}}>
          <svg width={40} height={10} viewBox="0 0 40 10">
            <path d="M0 5 L35 5 L40 5 L35 8 L35 2 Z" fill="#ff8888" opacity={0.7} />
          </svg>
        </div>
      );
    })}
  </AbsoluteFill>
);

const SombraCobija: React.FC<{s: number; k: number}> = ({s, k}) => {
  const respira = Math.sin(s * 0.7) * 8;
  return (
    <div style={{position: 'absolute', left: W / 2 - 200, top: 1000 + respira, width: 400, height: 500, opacity: k}}>
      <svg width={400} height={500} viewBox="0 0 400 500">
        <defs>
          <radialGradient id="sombraGrad" cx="50%" cy="20%" r="80%">
            <stop offset="0%" stopColor="#1a1a3a" stopOpacity={0.6 * k} />
            <stop offset="50%" stopColor="#0d0d20" stopOpacity={0.4 * k} />
            <stop offset="100%" stopColor="#050510" stopOpacity={0.2 * k} />
          </radialGradient>
          <radialGradient id="bordeLuz" cx="50%" cy="0%" r="60%">
            <stop offset="0%" stopColor="#ffe8b0" stopOpacity={0.5 * k} />
            <stop offset="100%" stopColor="#ffd080" stopOpacity={0} />
          </radialGradient>
        </defs>
        <ellipse cx={200} cy={480} rx={180} ry={40} fill="url(#sombraGrad)" />
        <path d="M20 480 Q 100 200, 200 100 Q 300 200, 380 480" fill="url(#sombraGrad)" />
        <path d="M20 480 Q 100 200, 200 100 Q 300 200, 380 480" fill="none" stroke="url(#bordeLuz)" strokeWidth={3} strokeLinecap="round" />
      </svg>
    </div>
  );
};

const FiguraDurmiendo: React.FC<{s: number; k: number}> = ({s, k}) => {
  const respira = Math.sin(s * 0.9) * 4;
  return (
    <div style={{position: 'absolute', left: W / 2 - 80, top: 1350 + respira, opacity: k}}>
      <svg width={160} height={200} viewBox="0 0 160 200">
        <ellipse cx={80} cy={195} rx={60} ry={8} fill="rgba(0,0,0,0.2)" />
        <path d="M40 140 Q 80 80, 120 140 L 130 180 L 30 180 Z" fill="#1a1a3a" />
        <ellipse cx={80} cy={60} rx={28} ry={30} fill="#1a1a3a" />
        <path d="M55 50 Q 80 30, 105 50" fill="none" stroke="#ffe8b0" strokeWidth={2} strokeLinecap="round" opacity={0.7 * k} />
        <ellipse cx={70} cy={55} rx={4} ry={3} fill="#ffe8b0" opacity={0.8} />
        <ellipse cx={90} cy={55} rx={4} ry={3} fill="#ffe8b0" opacity={0.8} />
      </svg>
    </div>
  );
};

const LuzVela: React.FC<{s: number; k: number}> = ({s, k}) => {
  const parpadeo = 0.85 + 0.15 * Math.sin(s * 8 + 0.3) * k;
  const respira = Math.sin(s * 1.1) * 2;
  return (
    <div style={{position: 'absolute', left: W / 2 + 120, top: 1250 + respira, opacity: k}}>
      <div style={{position: 'absolute', left: -40, top: -80, width: 80, height: 160, background: 'linear-gradient(180deg, #2a2010, #1a1008)', borderRadius: '40px 40px 8px 8px'}} />
      <div style={{position: 'absolute', left: -35, top: -85, width: 70, height: 100, background: `radial-gradient(ellipse at 50% 20%, rgba(255,220,120,${parpadeo}), rgba(255,180,60,${parpadeo * 0.6}) 50%, transparent 80%)`, borderRadius: '50%', filter: 'blur(20px)'}} />
      <div style={{position: 'absolute', left: -8, top: -110, width: 16, height: 30, background: `radial-gradient(ellipse, #fffef0, #ffd880 60%, #ff8800)`, borderRadius: '50% 50% 20% 20%', filter: 'blur(4px)', transformOrigin: 'center bottom', animation: `flame 0.18s infinite alternate`}} />
      <div style={{position: 'absolute', left: -120, top: -40, width: 240, height: 80, background: `radial-gradient(ellipse, rgba(255,220,120,${0.15 * parpadeo * k}), transparent 70%)`, borderRadius: '50%', filter: 'blur(10px)'}} />
    </div>
  );
};

const ParticulasPaz: React.FC<{s: number; k: number}> = ({s, k}) => (
  <AbsoluteFill>
    {Array.from({length: 50}).map((_, i) => {
      const x = (i * 149) % W + Math.sin(s * 0.4 + i) * 50;
      const y = H - ((i * 197 + s * (12 + (i % 5) * 5)) % (H + 200));
      const r = 2 + (i % 4);
      const brillo = 0.3 + 0.4 * Math.sin(s * 0.8 + i * 1.3);
      return <div key={i} style={{position: 'absolute', left: x, top: y, width: r, height: r, borderRadius: r, background: '#fffbe8', opacity: brillo * k * 0.7, filter: 'blur(0.5px)'}} />;
    })}
  </AbsoluteFill>
);

const ParticulasMiedo: React.FC<{s: number; k: number}> = ({s, k}) => (
  <AbsoluteFill>
    {Array.from({length: 30}).map((_, i) => {
      const x = (i * 167) % W + Math.cos(s * 0.6 + i) * 30;
      const y = 400 + (i * 233) % 600 + Math.sin(s * 0.5 + i) * 40;
      const r = 3 + (i % 3);
      return <div key={i} style={{position: 'absolute', left: x, top: y, width: r, height: r, borderRadius: r, background: '#ff6b6b', opacity: 0.4 * k * (0.5 + 0.5 * Math.sin(s * 2 + i)), filter: 'blur(1px)'}} />;
    })}
  </AbsoluteFill>
);

const Vigneta: React.FC<{k: number}> = ({k}) => (
  <AbsoluteFill style={{background: `radial-gradient(ellipse at 50% 55%, transparent 45%, rgba(5,5,20,${0.7 * k}) 100%)`}} />
);

export const Escena: React.FC = () => {
  const {s, lin} = useS();

  const miedoK = lin(MIEDO - 0.5, PECHO + 1.5, 1, 0, Easing.out(Easing.cubic));
  const abrigoK = lin(HABITA - 0.3, ALTISIMO + 2, 0, 1, Easing.inOut(Easing.cubic));
  const alasK = lin(PLUMAS - 0.5, ALAS + 3, 0, 1, Easing.inOut(Easing.cubic));
  const seguroK = lin(SEGURO - 0.5, SEGURO + 3, 0, 1, Easing.out(Easing.cubic));
  const saetasK = lin(SAETA - 0.3, VUELE + 1.5, 1, 0, Easing.inOut(Easing.cubic));
  const disueltasK = lin(TEMERAS, NOCTURNO + 1, 0, 1, Easing.out(Easing.cubic));
  const sombraK = lin(SOMBRA2 - 0.5, COBIJA + 2, 0, 1, Easing.inOut(Easing.cubic));
  const pazK = lin(DUERME - 0.5, AMEN + 1, 0, 1, Easing.inOut(Easing.cubic));
  const velaK = lin(VELA - 0.5, AMEN + 1, 0, 1, Easing.out(Easing.cubic));

  const amanecer = lin(PAZ - 0.5, AMEN, 0, 0.3, Easing.inOut(Easing.cubic));
  const zoom = 1.06 - 0.04 * (s / Math.max(DUR, 1)) + 0.02 * pazK;
  const deriva = Math.sin(s * 0.12) * 15;

  return (
    <AbsoluteFill style={{overflow: 'hidden', backgroundColor: '#050515'}}>
      <AbsoluteFill style={{transform: `scale(${zoom}) translateX(${deriva}px)`, transformOrigin: '50% 55%'}}>
        <Fondo colores={['#1a0d35', '#0d0820', '#050310']} manchas={['rgba(120,80,180,0.12)', 'rgba(255,160,100,0.08)']} particulas="#2a2a50" cantidad={20} />
        <Cielo k={amanecer} />
        <Estrellas s={s} op={1 - amanecer * 0.8} />
        <Luna s={s} k={1 - amanecer * 0.7} />
        <RayosLuna k={1 - amanecer * 0.7} s={s} />
        <NubesBajas s={s} miedo={miedoK} />
        <ParticulasMiedo s={s} k={miedoK} />
        <Pecho s={s} aprieta={miedoK} />
        <Escudo s={s} k={abrigoK} />
        <Alas s={s} k={alasK} />
        <Plumas s={s} k={alasK} />
        <Saetas s={s} k={saetasK} />
        <SaetasDisueltas s={s} k={disueltasK} />
        <SombraCobija s={s} k={sombraK} />
        <FiguraDurmiendo s={s} k={pazK} />
        <LuzVela s={s} k={velaK} />
        <ParticulasPaz s={s} k={pazK} />
      </AbsoluteFill>
      <Vigneta k={1} />
    </AbsoluteFill>
  );
};
